package com.limitbeyond.engagement.internal;
import com.limitbeyond.engagement.domain.Feedback;import com.limitbeyond.engagement.persistence.FeedbackRepository;import com.limitbeyond.engagement.web.FeedbackDtos;import com.limitbeyond.identity.api.UserFacade;import com.limitbeyond.shared.error.DomainException;import com.limitbeyond.shared.rls.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service
public class FeedbackService{
 private final FeedbackRepository repository;private final UserFacade users;public FeedbackService(FeedbackRepository repository,UserFacade users){this.repository=repository;this.users=users;}
 @Transactional public FeedbackDtos.FeedbackView create(FeedbackDtos.CreateRequest r){AuthContext c=requireGym();if(!c.hasRole("MEMBER"))throw DomainException.forbidden("submit member feedback");if(!c.appliesAt(r.locationId()))throw DomainException.notFound("Location");return view(repository.save(new Feedback(c.gymId(),r.locationId(),c.userId(),r.title(),r.category(),r.body(),r.anonymous())),c);}
 @Transactional(readOnly=true)public List<FeedbackDtos.FeedbackView> mine(){AuthContext c=requireGym();return repository.findByAuthorUserIdOrderByCreatedAtDesc(c.userId()).stream().map(f->view(f,c)).toList();}
 @Transactional(readOnly=true)public FeedbackDtos.FeedbackView one(UUID id){AuthContext c=requireGym();return view(accessible(id,c),c);}
 @Transactional(readOnly=true)public List<FeedbackDtos.FeedbackView> queue(UUID locationId){AuthContext c=requireGym();requireStaffAt(c,locationId);return repository.findByLocationIdOrderByCreatedAtDesc(locationId).stream().map(f->view(f,c)).toList();}
 @Transactional public FeedbackDtos.FeedbackView update(UUID id,FeedbackDtos.UpdateRequest r){AuthContext c=requireGym();Feedback f=accessible(id,c);if(!f.getAuthorUserId().equals(c.userId())&&!c.isAdmin())throw DomainException.notFound("Feedback");f.update(r.title(),r.category(),r.body(),r.anonymous());return view(f,c);}
 @Transactional public void delete(UUID id){AuthContext c=requireGym();Feedback f=accessible(id,c);if(!f.getAuthorUserId().equals(c.userId())&&!c.isAdmin())throw DomainException.notFound("Feedback");repository.delete(f);}
 @Transactional public FeedbackDtos.FeedbackView respond(UUID id,FeedbackDtos.RespondRequest r){AuthContext c=requireGym();Feedback f=staffFeedback(id,c);f.addResponse(c.userId(),r.body());return view(f,c);}
 @Transactional public FeedbackDtos.FeedbackView updateResponse(UUID id,UUID responseId,FeedbackDtos.RespondRequest r){AuthContext c=requireGym();Feedback f=staffFeedback(id,c);var response=f.response(responseId);if(response==null)throw DomainException.notFound("Feedback response");if(!response.getAuthorUserId().equals(c.userId())&&!c.isAdmin())throw DomainException.notFound("Feedback response");response.update(r.body());return view(f,c);}
 @Transactional public FeedbackDtos.FeedbackView deleteResponse(UUID id,UUID responseId){AuthContext c=requireGym();Feedback f=staffFeedback(id,c);var response=f.response(responseId);if(response==null)throw DomainException.notFound("Feedback response");if(!response.getAuthorUserId().equals(c.userId())&&!c.isAdmin())throw DomainException.notFound("Feedback response");f.removeResponse(responseId);return view(f,c);}
 @Transactional public FeedbackDtos.FeedbackView setResolved(UUID id,boolean resolved){AuthContext c=requireGym();Feedback f=staffFeedback(id,c);if(resolved)f.resolve();else f.reopen();return view(f,c);}
 private AuthContext requireGym(){AuthContext c=AuthContextHolder.get();if(!c.isAuthenticated()||c.gymId()==null)throw DomainException.forbidden("use feedback");return c;}
 private Feedback accessible(UUID id,AuthContext c){Feedback f=repository.findById(id).orElseThrow(()->DomainException.notFound("Feedback"));if(!f.getAuthorUserId().equals(c.userId()))requireStaffAt(c,f.getLocationId());return f;}
 private Feedback staffFeedback(UUID id,AuthContext c){Feedback f=repository.findById(id).orElseThrow(()->DomainException.notFound("Feedback"));requireStaffAt(c,f.getLocationId());return f;}
 private void requireStaffAt(AuthContext c,UUID locationId){if(!c.isAllowed(locationId,"GYM_OWNER","LOCATION_ADMIN","TRAINER"))throw DomainException.notFound("Feedback");}
 private FeedbackDtos.FeedbackView view(Feedback f,AuthContext c){boolean owned=f.getAuthorUserId().equals(c.userId());boolean staff=c.isAdmin()||c.hasRole("TRAINER");String author=f.isAnonymous()&&staff&&!owned?"Anonymous":name(f.getAuthorUserId());return new FeedbackDtos.FeedbackView(f.getId(),f.getLocationId(),f.getTitle(),f.getCategory(),f.getBody(),f.getState(),f.isAnonymous(),author,f.getCreatedAt(),f.getUpdatedAt(),owned,f.getResponses().stream().map(x->new FeedbackDtos.ResponseView(x.getId(),name(x.getAuthorUserId()),x.getBody(),x.getCreatedAt(),x.getUpdatedAt(),x.getAuthorUserId().equals(c.userId()))).toList());}
 private String name(UUID id){return users.findContact(id).map(u->(u.firstName()+" "+u.lastName()).trim()).orElse("User");}
}
